.check-day i { position: absolute; bottom: 5px; left: calc(50% - 2px); width: 4px; height: 4px; background: #232724; border-radius: 50%; transform: scale(0); transition: transform 340ms var(--check-ease); }
.check-day input:checked + span { background: var(--check-paper); color: var(--check-ink); border-color: var(--check-paper); }
