.check-tiles { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px; padding: 8px; }
.check-tile { position: relative; min-width: 0; cursor: pointer; }
.check-tile__face { display: flex; min-height: 128px; flex-direction: column; align-items: center; justify-content: center; gap: 10px; border: 1px solid #626a65; border-radius: 10px; background: #161917; color: #b7c0b9; transition: border-color 340ms ease, background-color 340ms ease, color 340ms ease; font-size: 12px; }
.tile-art { width: 29px; height: 29px; transition: transform 420ms var(--check-ease); }
