.temperature-meter { position: relative; height: 12px; margin: 26px 6px 10px 8px; border: 0; border-radius: 12px; background: #424847; box-shadow: inset 0 1px 2px #0003; }
.temperature-meter span { position: absolute; inset: 3px 4px; transform: scaleX(var(--fraction,.6)); transform-origin: left; border-radius: inherit; background: #dce5df; transition: transform 200ms var(--slider-ease); }
.temperature-meter i { position: absolute; width: 22px; height: 22px; border: 5px solid #424847; background: #dce5df; border-radius: 50%; left: -6px; top: -5px; }
.slider-temperature .slider-input::-webkit-slider-thumb { border-radius: 50%; }
.slider-temperature .slider-input::-moz-range-thumb { border-radius: 50%; }
.slider-bipolar .slider-rail::after { content: ""; position: absolute; top: -5px; left: 50%; height: 14px; width: 1px; background: #aeb8b1; }
.balance-symbol { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 24px; color: #bfcac2; font-size: 12px; }
.balance-symbol i { position: relative; width: 92px; height: 4px; background: #69786e; border-radius: 6px; }
.balance-symbol i::after { content: ""; position: absolute; width: 16px; height: 16px; border: 1px solid #e7ece9; background: #303931; border-radius: 50%; top: -6px; left: calc(var(--fraction,.5) * 76px); transition: left 200ms var(--slider-ease); }
.exposure-scale, .hour-marks { display: flex; justify-content: space-between; color: #b5bfb8; font-size: 11px; }
.exposure-scale { border-top: 8px solid transparent; border-image: repeating-linear-gradient(90deg,#849087 0 1px,transparent 1px 8px) 8; padding-top: 6px; }
.slider-exposure .slider-input::-webkit-slider-thumb { width: 12px; border-radius: 6px; }
.slider-exposure .slider-input::-moz-range-thumb { width: 10px; border-radius: 6px; }
.slider-exposure .slider-rail { left: 6px; right: 6px; }
.slider-segments .slider-rail { height: 12px; top: 17px; border-radius: 2px; }
.slider-segments .slider-rail::after { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(90deg,transparent 0 calc(10% - 3px),#202222 calc(10% - 3px) 10%); }
.slider-segments .slider-input::-webkit-slider-thumb { border-radius: 8px; height: 28px; margin-top: -12px; }
.slider-segments .slider-input::-moz-range-thumb { border-radius: 8px; height: 26px; }
.rating-stars { display: flex; justify-content: space-between; gap: 2px; margin-top: 18px; }
.rating-choice { display: grid; place-items: center; flex: 1; min-width: 0; min-height: 44px; padding: 4px; background: transparent; color: inherit; border: 0; border-radius: 12px; cursor: pointer; transition: background-color 220ms ease; }
.rating-choice:hover { background: #ffffff08; }
.rating-choice:hover .rating-star { transform: translateY(-2px); }
.rating-choice:active .rating-star { transform: scale(.94); }
.rating-star { width: 28px; height: 28px; stroke: #a9b4ac; stroke-width: 1.2; stroke-linejoin: round; fill: none; transition: transform 220ms var(--slider-ease); }
.star-solid { fill: #e4ebe6; stroke: #e4ebe6; clip-path: inset(0 calc(90% - var(--star-fill,0) * 80%) 0 0); }
.sl-slider .slider-input:focus-visible { outline-offset: -2px; }
.slider-rating .slider-input::-webkit-slider-thumb { border-radius: 50%; }
.slider-rating .slider-input::-moz-range-thumb { border-radius: 50%; }
.hour-marks { padding-inline: 6px; }
.hour-marks span::before { content: ""; display: block; width: 1px; height: 6px; margin: 0 auto 8px; background: #78867c; }
.slider-hours .slider-input::-webkit-slider-thumb { border-radius: 8px; }
.slider-hours .slider-input::-moz-range-thumb { border-radius: 8px; }
.slider-distance .slider-track { margin-top: 45px; }
.distance-bubble { position: absolute; left: calc(12px + (100% - 24px) * var(--fraction,.35)); bottom: 44px; transform: translateX(-50%); padding: 5px 8px; min-width: 40px; font-size: 11px; text-align: center; white-space: nowrap; color: #202222; background: #e1e9e3; border-radius: 7px; pointer-events: none; }
.distance-bubble::after { content: ""; position: absolute; bottom: -3px; left: calc(50% - 3px); width: 6px; height: 6px; transform: rotate(45deg); background: inherit; }
.slider-meter .slider-track { margin: 18px auto 6px; }
.slider-meter .slider-rail { width: 22px; left: 12px; border-radius: 20px; background: #4d5a51; }
.slider-meter .slider-fill { background: #becbc2; }
.slider-meter .slider-input::-webkit-slider-thumb { width: 32px; height: 24px; margin-left: -14px; border-radius: 12px; }
.slider-meter .slider-input::-moz-range-thumb { width: 30px; height: 22px; border-radius: 12px; }
.meter-endpoints { display: flex; justify-content: space-between; color: #b6c2b9; font-size: 12px; }
.mixer-group { box-sizing: border-box; width: min(320px,100%); min-width: 0; padding: 16px; margin: 0; border: 1px solid #ffffff0b; border-radius: 14px; background: #202222; color: #edf1ee; font-family: 'Instrument Sans',sans-serif; box-shadow: inset 0 1px #ffffff0d,0 2px 5px #00000010; }
.mixer-title { margin: 0 0 14px; font-size: 14px; }
.mixer-channels { display: flex; gap: 8px; }
.slider-channel { flex: 1; width: 0; padding: 8px 3px; border-radius: 8px; background: #171b18; box-shadow: none; }
.slider-channel .slider-header { flex-direction: column; gap: 5px; font-size: 12px; }
.slider-channel .slider-header output { font-size: 11px; color: #b8c5bc; }
.slider-channel .slider-track { width: 40px; height: 132px; margin: 12px auto 0; }
.slider-channel .slider-input { width: 40px; height: 132px; }
.slider-channel .slider-rail { left: 18px; }
.slider-channel .slider-ends { display: none; }
.type-preview { height: 80px; display: grid; place-items: center; margin-top: 12px; background: #161a17; border-radius: 8px; overflow: hidden; }
.type-preview span { font-size: var(--preview-value,28px); line-height: 1; transition: font-size 200ms var(--slider-ease); }
.radius-preview { display: grid; place-items: center; margin-top: 18px; height: 84px; }
.radius-preview span { width: 80px; height: 80px; background: #d3dfd6; border-radius: var(--preview-value,16px); box-shadow: inset 0 0 0 1px #f1f5f2; }
.opacity-preview { height: 80px; margin-top: 20px; border-radius: 8px; overflow: hidden; background: conic-gradient(#4b574e 25%,#26302a 0 50%,#4b574e 0 75%,#26302a 0) 0 0/16px 16px; }
.opacity-preview span { display: block; height: 100%; background: #e5ede7; opacity: var(--fraction,.7); transition: opacity 200ms var(--slider-ease); }
.slider-temperature .slider-input:active::-webkit-slider-thumb, .slider-rating .slider-input:active::-webkit-slider-thumb { border-radius: 50%; }
.slider-scrub .slider-input:active::-webkit-slider-thumb { border-radius: 2px; }
.slider-exposure .slider-input:active::-webkit-slider-thumb { border-radius: 6px; }
.speed-stops button:hover:not(.is-current) { background: #ffffff0a; }
[data-study] .sl-slider:not([data-interacted]) .zoom-frame,
[data-study] .sl-slider:not([data-interacted]) .temperature-meter span,
[data-study] .sl-slider:not([data-interacted]) .rating-star { transition: none; }
@media(max-width:420px) { .speed-stops { font-size: 10px; } .speed-stops button { padding-inline: 4px; } .mixer-group { padding: 12px; } .slider-channel { padding: 8px 2px; } .mixer-channels { gap: 6px; } .slider-channel .slider-header { font-size: 11px; } }
@media(prefers-reduced-motion:reduce) { .sl-slider *, .sl-slider *::before, .sl-slider *::after { transition: none !important; } }

