.surface-option:hover,.format-option:hover,.insert-option:hover { background: transparent; }
.surface-option[aria-checked="true"],.format-option[aria-checked="true"],.insert-option[aria-current="true"] { border-color: #b9c7bf66; background: transparent; }
.surface-sample { display: block; width: 100%; height: 53px; border-radius: 9px; background: #343938; }
.sample-outline { border: 1px solid #9eaaa4; background: transparent; }
.sample-raised { box-shadow: inset 0 1px #ffffff30,0 4px 6px #0005; background: linear-gradient(#454b48,#272c2a); }
.surface-option .menu-check { display: block; margin: 0 auto; width: 20px; height: 20px; }
[data-appearance="outline"] > .menu-trigger { background: #171a19; border-color: #9eaaa4; }
[data-appearance="raised"] > .menu-trigger { background: linear-gradient(#414643,#252a27); box-shadow: inset 0 1px #ffffff30,0 5px 8px #0003; }
