.activity-line{display:flex;position:relative;align-items:center;gap:14px;min-height:58px}.activity-line>span{width:7px;height:7px;border-radius:50%;border:1px solid #b8c9be}.activity-line:first-child:after{content:'';position:absolute;top:34px;left:3px;height:47px;width:1px;background:#9aafa13a}
